#!/bin/sh
# Injects "bypass" routing rules into the config generated by the upstream
# entrypoint, then starts the real Xray binary. Destinations in BYPASS_JSON
# (a JSON array of domains, IPs/CIDRs or geoip/geosite values) go out through
# the "direct" outbound instead of the VLESS tunnel.
set -eu

REAL_XRAY="${REAL_XRAY:-/usr/local/bin/Xray}"
BYPASS_JSON="${BYPASS_JSON:-[]}"

# Locate the config passed as "-config PATH" or "-config=PATH".
config=""
prev=""
for arg in "$@"; do
  if [ "$prev" = "-config" ]; then
    config="$arg"
    break
  fi
  case "$arg" in
    -config=*)
      config="${arg#-config=}"
      break
      ;;
  esac
  prev="$arg"
done

[ -n "$config" ] && [ -f "$config" ] || exec "$REAL_XRAY" "$@"

count="$(printf '%s' "$BYPASS_JSON" | jq 'length' 2>/dev/null || echo 0)"
if [ "${count:-0}" -gt 0 ]; then
  tmp="$(mktemp)"
  if jq --argjson bypass "$BYPASS_JSON" '
      # An entry is treated as an IP/CIDR when it is geoip:, an IPv4 address
      # or CIDR, or an IPv6 address or CIDR. Everything else is a domain rule.
      def is_ip:
        test("^geoip:") or
        test("^[0-9]{1,3}(\\.[0-9]{1,3}){3}(/[0-9]{1,2})?$") or
        (contains(":") and test("^[0-9A-Fa-f:]+(/[0-9]{1,3})?$"));

      ($bypass | map(select(is_ip))) as $ips
      | ($bypass | map(select(is_ip | not))) as $domains
      | .routing = (.routing // {"rules": []})
      | .routing.rules = (
          (if ($domains | length) > 0
             then [{"type": "field", "domain": $domains, "outboundTag": "direct"}]
             else [] end)
          + (if ($ips | length) > 0
             then [{"type": "field", "ip": $ips, "outboundTag": "direct"}]
             else [] end)
          + (.routing.rules // [])
        )
    ' "$config" > "$tmp" 2>/dev/null; then
    mv "$tmp" "$config"
  else
    rm -f "$tmp"
  fi
fi

exec "$REAL_XRAY" "$@"
